package cron

import (
	"fmt"
	"time"
)

// CronNextRunDecisionFunc is the injectable next-run decision used by the
// pure run-completion helper.
type CronNextRunDecisionFunc func(ParsedSchedule, int64, int, time.Time) CronRunDecision

// CronRunCompletionState is the post-run state that should be persisted after
// one executor fire.
type CronRunCompletionState struct {
	Job      Job
	Run      Run
	Decision CronRunDecision
	Evidence *CronUnavailableEvidence
	Terminal bool
}

// CronRunCompletion updates a job/run pair after one executor fire without
// touching stores, goroutines, scheduler ticks, or wall-clock time.
func CronRunCompletion(job Job, run Run, parsed ParsedSchedule, now time.Time, next CronNextRunDecisionFunc) CronRunCompletionState {
	if next == nil {
		next = CronNextRunDecision
	}
	job.LastRunUnix = run.StartedAt
	job.LastStatus = run.Status
	if job.RepeatCompleted < 0 {
		job.RepeatCompleted = 0
	}
	job.RepeatCompleted++
	if job.Repeat > 0 {
		parsed.Repeat = job.Repeat
	}

	decision := next(parsed, job.LastRunUnix, job.RepeatCompleted, now)
	state := CronRunCompletionState{
		Job:      job,
		Run:      run,
		Decision: decision,
	}

	if decision.Exhausted {
		return state.withTerminalEvidence(evidenceOrDefault(decision.Unavailable, "repeat_exhausted", "repeat limit exhausted"))
	}

	if parsed.Kind == ScheduleKindOnce && oneShotCompletionTerminal(decision, now) {
		return state.withTerminalEvidence(evidenceOrDefault(decision.Unavailable, "oneshot_completed", "one-shot schedule has no next run"))
	}

	if isRecurringScheduleKind(parsed.Kind) && recurringNextRunUnavailable(decision, now) {
		evidence := recurringNextRunUnavailableEvidence(parsed, decision)
		state.Evidence = evidence
		state.Job.LastStatus = "error"
		state.Run.Status = "error"
		state.Run.ErrorMsg = appendRunCompletionEvidence(state.Run.ErrorMsg, evidence, decision.Unavailable)
		return state
	}

	return state
}

func cronRunCompletionForJob(job Job, run Run, now time.Time, next CronNextRunDecisionFunc) CronRunCompletionState {
	parsed, err := ParseCronSchedule(job.Schedule, now)
	if err != nil {
		return baselineRunCompletion(job, run)
	}
	return CronRunCompletion(job, run, parsed, now, next)
}

func baselineRunCompletion(job Job, run Run) CronRunCompletionState {
	job.LastRunUnix = run.StartedAt
	job.LastStatus = run.Status
	if job.RepeatCompleted < 0 {
		job.RepeatCompleted = 0
	}
	job.RepeatCompleted++
	return CronRunCompletionState{
		Job: job,
		Run: run,
	}
}

func (s CronRunCompletionState) withTerminalEvidence(evidence *CronUnavailableEvidence) CronRunCompletionState {
	s.Terminal = true
	s.Evidence = evidence
	s.Job.Paused = true
	s.Job.LastStatus = "completed"
	s.Run.ErrorMsg = appendRunCompletionEvidence(s.Run.ErrorMsg, evidence, nil)
	return s
}

func isRecurringScheduleKind(kind ScheduleKind) bool {
	return kind == ScheduleKindCron || kind == ScheduleKindInterval
}

func recurringNextRunUnavailable(decision CronRunDecision, now time.Time) bool {
	if decision.Unavailable != nil {
		return true
	}
	if decision.NextRun.IsZero() {
		return true
	}
	return !decision.NextRun.After(now)
}

func oneShotCompletionTerminal(decision CronRunDecision, now time.Time) bool {
	if decision.Unavailable != nil {
		return true
	}
	if decision.NextRun.IsZero() {
		return true
	}
	return !decision.NextRun.After(now)
}

func recurringNextRunUnavailableEvidence(parsed ParsedSchedule, decision CronRunDecision) *CronUnavailableEvidence {
	detail := "next-run decision returned no future time"
	if decision.Unavailable != nil {
		switch {
		case decision.Unavailable.Message != "":
			detail = decision.Unavailable.Message
		case decision.Unavailable.Code != "":
			detail = decision.Unavailable.Code
		}
	}
	display := parsed.Display
	if display == "" {
		display = parsed.Expr
	}
	if display == "" {
		display = string(parsed.Kind)
	}
	return NewUnavailableEvidence(
		"cron_next_run_unavailable",
		fmt.Sprintf("next run unavailable for %s schedule %q: %s", parsed.Kind, display, detail),
	)
}

func evidenceOrDefault(evidence *CronUnavailableEvidence, code, message string) *CronUnavailableEvidence {
	if evidence != nil {
		return evidence
	}
	return NewUnavailableEvidence(code, message)
}

func appendRunCompletionEvidence(existing string, evidence, cause *CronUnavailableEvidence) string {
	if evidence == nil {
		return existing
	}
	text := evidence.Code
	if evidence.Message != "" {
		text = fmt.Sprintf("%s: %s", evidence.Code, evidence.Message)
	}
	if cause != nil && cause.Code != "" && cause.Code != evidence.Code {
		if cause.Message != "" {
			text = fmt.Sprintf("%s (cause=%s: %s)", text, cause.Code, cause.Message)
		} else {
			text = fmt.Sprintf("%s (cause=%s)", text, cause.Code)
		}
	}
	if existing == "" {
		return text
	}
	return existing + "; " + text
}

package cron

import (
	"errors"
	"fmt"
	"io"
	"sync"
)

// ReleaseEvidenceCode classifies one resource-release outcome inside a cron
// run's release ledger. The vocabulary mirrors the per-run evidence emitted
// by upstream Hermes 9b55365f's run_job/agent.close() reaping; Gormes will
// later surface these into run_completion / heartbeat without changing the
// codes.
type ReleaseEvidenceCode string

const (
	ReleaseEvidenceSubprocessKilled     ReleaseEvidenceCode = "cron_release_subprocess_killed"
	ReleaseEvidenceSessionDBClosed      ReleaseEvidenceCode = "cron_release_session_db_closed"
	ReleaseEvidenceHTTPIdleClosed       ReleaseEvidenceCode = "cron_release_http_idle_closed"
	ReleaseEvidenceHTTPIdleClosedFailed ReleaseEvidenceCode = "cron_release_http_idle_closed_failed"
	ReleaseEvidenceSkippedNoResource    ReleaseEvidenceCode = "cron_release_skipped_no_resource"
)

// ReleaseEvidence is one entry in the per-run release log. Fields carries
// optional structured context (pid, label, error) without coupling the
// helper to a specific telemetry sink.
type ReleaseEvidence struct {
	Code   ReleaseEvidenceCode
	Label  string
	Fields map[string]any
}

// SubprocessKiller is the narrow seam used to terminate spawned tool
// subprocesses without depending on os.Process inside the helper. Unit
// tests pass a fake; future Executor binding will pass a real syscall-backed
// implementation.
type SubprocessKiller interface {
	Kill(pid int) error
}

type closerEntry struct {
	label  string
	closer io.Closer
	kind   ReleaseEvidenceCode
}

// RunReleaseLedger records the per-run resources a cron Executor.Run
// acquired and releases them deterministically when Release is called.
//
// Registration order is preserved on release; partial failures continue to
// the next entry; a second Release on the same ledger is a no-op recorded
// as cron_release_skipped_no_resource. The helper does not start a kernel
// turn, hit a provider, manage MCP stdio runtimes, or change the Scheduler
// goroutine lifecycle — Executor binding is a dependent row.
type RunReleaseLedger struct {
	mu       sync.Mutex
	closers  []closerEntry
	pids     []int
	released bool
}

// NewRunReleaseLedger constructs an empty ledger. Callers register
// resources through Register* and call Release exactly once at run
// completion (success, kernel-error, ctx-cancel, or timeout paths).
func NewRunReleaseLedger() *RunReleaseLedger {
	return &RunReleaseLedger{}
}

// RegisterCloser records an io.Closer the executor opened for this run
// (typically a per-session SQLite store). label is used as evidence Label.
func (l *RunReleaseLedger) RegisterCloser(label string, closer io.Closer) {
	if closer == nil {
		return
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.closers = append(l.closers, closerEntry{label: label, closer: closer, kind: ReleaseEvidenceSessionDBClosed})
}

// RegisterIdleClosable records an outbound HTTP RoundTripper or other
// idle-conn closable that should be reaped at run end.
func (l *RunReleaseLedger) RegisterIdleClosable(label string, closer io.Closer) {
	if closer == nil {
		return
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.closers = append(l.closers, closerEntry{label: label, closer: closer, kind: ReleaseEvidenceHTTPIdleClosed})
}

// RegisterSubprocess records a tool-subprocess PID to terminate at run
// end. The helper does not spawn or own the subprocess; it only forwards
// the PID to a SubprocessKiller passed into Release.
func (l *RunReleaseLedger) RegisterSubprocess(pid int) {
	if pid <= 0 {
		return
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.pids = append(l.pids, pid)
}

// Release closes every registered resource in registration order. A nil
// killer is treated as no-op for subprocesses. Errors are aggregated and
// returned via errors.Join while the helper continues to the next entry.
// A second call returns a single skipped_no_resource evidence entry and
// does not double-release.
func (l *RunReleaseLedger) Release(killer SubprocessKiller) ([]ReleaseEvidence, error) {
	l.mu.Lock()
	if l.released {
		l.mu.Unlock()
		return []ReleaseEvidence{{Code: ReleaseEvidenceSkippedNoResource, Fields: map[string]any{"reason": "already_released"}}}, nil
	}
	l.released = true
	closers := l.closers
	pids := l.pids
	l.closers = nil
	l.pids = nil
	l.mu.Unlock()

	if len(closers) == 0 && len(pids) == 0 {
		return []ReleaseEvidence{{Code: ReleaseEvidenceSkippedNoResource, Fields: map[string]any{"reason": "no_resources_registered"}}}, nil
	}

	evidence := make([]ReleaseEvidence, 0, len(closers)+len(pids))
	var errs []error

	for _, entry := range closers {
		err := entry.closer.Close()
		if err != nil {
			failedCode := releaseFailureCode(entry.kind)
			evidence = append(evidence, ReleaseEvidence{
				Code:   failedCode,
				Label:  entry.label,
				Fields: map[string]any{"error": err.Error()},
			})
			errs = append(errs, fmt.Errorf("%s %q: %w", entry.kind, entry.label, err))
			continue
		}
		evidence = append(evidence, ReleaseEvidence{
			Code:   entry.kind,
			Label:  entry.label,
			Fields: map[string]any{},
		})
	}

	for _, pid := range pids {
		fields := map[string]any{"pid": pid}
		if killer == nil {
			fields["error"] = "no killer supplied"
			evidence = append(evidence, ReleaseEvidence{Code: ReleaseEvidenceSubprocessKilled, Fields: fields})
			continue
		}
		if err := killer.Kill(pid); err != nil {
			fields["error"] = err.Error()
			evidence = append(evidence, ReleaseEvidence{Code: ReleaseEvidenceSubprocessKilled, Fields: fields})
			errs = append(errs, fmt.Errorf("kill pid %d: %w", pid, err))
			continue
		}
		evidence = append(evidence, ReleaseEvidence{Code: ReleaseEvidenceSubprocessKilled, Fields: fields})
	}

	if len(errs) > 0 {
		return evidence, errors.Join(errs...)
	}
	return evidence, nil
}

func releaseFailureCode(kind ReleaseEvidenceCode) ReleaseEvidenceCode {
	switch kind {
	case ReleaseEvidenceHTTPIdleClosed:
		return ReleaseEvidenceHTTPIdleClosedFailed
	case ReleaseEvidenceSessionDBClosed:
		return ReleaseEvidenceCode("cron_release_session_db_closed_failed")
	default:
		return ReleaseEvidenceCode(string(kind) + "_failed")
	}
}

package cron

import "context"

// DeliverySink is the abstraction between the cron executor and the
// actual outbound channel. cmd/gormes/telegram.go provides a Telegram
// implementation; future Slack/Discord adapters plug in the same way
// without the cron package learning about them.
//
// Implementations:
//   - Own their rate limiting + retries internally (cron won't retry
//     on failure — it records the delivery_status and moves on).
//   - Return a non-nil error on failure so the executor can log it.
type DeliverySink interface {
	Deliver(ctx context.Context, text string) error
}

// FuncSink adapts a plain function to the DeliverySink interface —
// convenient for test injections and for wrapping the Telegram bot's
// existing send method without wrapping in a struct.
type FuncSink func(ctx context.Context, text string) error

// Deliver satisfies DeliverySink.
func (f FuncSink) Deliver(ctx context.Context, text string) error {
	return f(ctx, text)
}

// Package cron is the Phase 2.D proactive scheduler. Jobs stored in
// bbolt; per-run audit rows in SQLite; agent turns isolated via an
// ephemeral session id per fire. See spec at
// webpages/docs/superpowers/specs/2026-04-20-gormes-phase2d-cron-design.md.
package cron

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"time"

	rc "github.com/robfig/cron/v3"
)

// Job is a scheduled agent prompt. Persisted as a JSON blob under its
// ID as key in the cron_jobs bbolt bucket.
type Job struct {
	ID              string          `json:"id"`                         // 16-byte random hex — unique within one DB
	Name            string          `json:"name"`                       // operator-friendly label; must be unique
	Schedule        string          `json:"schedule"`                   // operator schedule string or cron expression
	Prompt          string          `json:"prompt"`                     // user-facing prompt, WITHOUT the [SYSTEM:] prefix
	Deliver         string          `json:"deliver,omitempty"`          // comma-separated delivery targets: origin, local, platform, or platform:chat[:thread]
	Origin          *DeliveryOrigin `json:"origin,omitempty"`           // source chat for origin delivery, when the job was created from a channel
	Paused          bool            `json:"paused"`                     // default false; if true, scheduler ignores
	CreatedAt       int64           `json:"created_at"`                 // unix seconds
	LastRunUnix     int64           `json:"last_run_unix"`              // 0 when never run
	LastStatus      string          `json:"last_status"`                // "success"|"timeout"|"error"|"suppressed"|""
	Repeat          int             `json:"repeat,omitempty"`           // finite repeat limit; 0 means unbounded/default
	RepeatCompleted int             `json:"repeat_completed,omitempty"` // completed repeat count for summaries
	Model           string          `json:"model,omitempty"`            // optional per-job model override
	Provider        string          `json:"provider,omitempty"`         // optional per-job provider override
	Skills          []string        `json:"skills,omitempty"`           // ordered skills loaded before the prompt
	EnabledToolsets []string        `json:"enabled_toolsets,omitempty"` // optional toolset restriction
	Workdir         string          `json:"workdir,omitempty"`          // optional job working directory
	Script          string          `json:"script,omitempty"`           // optional pre-run script path
	NoAgent         bool            `json:"no_agent,omitempty"`         // true when script output is the job and no agent turn is constructed
	ContextFrom     []string        `json:"context_from,omitempty"`     // upstream cron job IDs for future context chaining
}

// NewJob constructs a Job with a fresh random ID and the current time
// as CreatedAt. The caller still needs to validate the schedule and
// call Store.Create.
func NewJob(name, schedule, prompt string) Job {
	return Job{
		ID:        newID(),
		Name:      name,
		Schedule:  schedule,
		Prompt:    prompt,
		Paused:    false,
		CreatedAt: time.Now().Unix(),
	}
}

// ValidateSchedule parses the cron expression via robfig/cron/v3's
// standard parser, returning a typed error on rejection. Accepts
// 5-field standard cron and @shortcut forms (@daily, @hourly,
// @every 30m, etc.).
func ValidateSchedule(expr string) error {
	if expr == "" {
		return fmt.Errorf("cron: schedule is empty")
	}
	_, err := rc.ParseStandard(expr)
	if err != nil {
		return fmt.Errorf("cron: invalid schedule %q: %w", expr, err)
	}
	return nil
}

// newID generates a 16-byte (32-hex-char) random ID. Not ULID, not
// UUID — we don't need the timestamp encoding, just uniqueness within
// one bbolt file. crypto/rand is stdlib so no new deps.
func newID() string {
	var b [16]byte
	_, _ = rand.Read(b[:])
	return hex.EncodeToString(b[:])
}

package cron

import (
	"context"
	"fmt"
	"log/slog"
	"strings"
)

// CronHeartbeatPrefix is the verbatim port of upstream Hermes'
// cron/scheduler.py cron_hint. Prepended to every scheduled-job
// prompt so the LLM knows:
//   - Its output is auto-delivered — don't call send_message
//   - It can return exactly "[SILENT]" (and nothing else) to
//     suppress delivery
//
// Matching upstream byte-for-byte matters: if a future Hermes bump
// changes the wording, we want to notice (the byte-match test
// TestCronHeartbeatPrefixConstantValue flags drift on
// any of the load-bearing phrases).
const CronHeartbeatPrefix = "[IMPORTANT: You are running as a scheduled cron job. " +
	"DELIVERY: Your final response will be automatically delivered " +
	"to the user — do NOT use send_message or try to deliver " +
	"the output yourself. Just produce your report/output as your " +
	"final response and the system handles the rest. " +
	"SILENT: If there is genuinely nothing new to report, respond " +
	"with exactly \"[SILENT]\" (nothing else) to suppress delivery. " +
	"Never combine [SILENT] with content — either report your " +
	"findings normally, or say [SILENT] and nothing more.]\n\n"

// BuildPrompt prepends the cron heartbeat prefix to the operator's
// prompt. The concatenated result is what the kernel sees as the
// user message for the cron turn.
func BuildPrompt(userPrompt string) string {
	return CronHeartbeatPrefix + userPrompt
}

// BuildPromptForJob prepends bounded context_from output before the job prompt,
// then applies the standard cron heartbeat.
func BuildPromptForJob(ctx context.Context, job Job, runStore *RunStore, log *slog.Logger) string {
	body := job.Prompt
	blocks := contextFromBlocks(ctx, job.ContextFrom, runStore, log)
	if len(blocks) > 0 {
		body = strings.Join(blocks, "") + body
	}
	return BuildPrompt(body)
}

const (
	maxContextFromOutputChars = 8000
	contextFromTruncated      = "\n\n[... output truncated ...]"
)

func contextFromBlocks(ctx context.Context, sourceIDs []string, runStore *RunStore, log *slog.Logger) []string {
	if len(sourceIDs) == 0 {
		return nil
	}
	if log == nil {
		log = slog.Default()
	}
	if runStore == nil {
		log.Warn("cron: context_from skipped because run store is unavailable")
		return nil
	}
	blocks := make([]string, 0, len(sourceIDs))
	for _, rawID := range sourceIDs {
		sourceID := strings.TrimSpace(rawID)
		if !validContextFromJobID(sourceID) {
			log.Warn("cron: context_from skipped invalid job id", "job_id", sourceID)
			continue
		}
		output, ok, err := runStore.LatestCompletedOutput(ctx, sourceID)
		if err != nil {
			log.Warn("cron: context_from output read failed", "job_id", sourceID, "err", err)
			continue
		}
		output = strings.TrimSpace(output)
		if !ok || output == "" {
			log.Info("cron: context_from source has no completed output", "job_id", sourceID)
			continue
		}
		blocks = append(blocks, formatContextFromBlock(sourceID, boundContextFromOutput(output)))
	}
	return blocks
}

func formatContextFromBlock(sourceID, output string) string {
	return fmt.Sprintf(
		"## Output from job '%s'\n"+
			"The following is the most recent output from a preceding cron job. Use it as context for your analysis.\n\n"+
			"```\n%s\n```\n\n",
		sourceID,
		output,
	)
}

func boundContextFromOutput(output string) string {
	if len(output) <= maxContextFromOutputChars {
		return output
	}
	return output[:maxContextFromOutputChars] + contextFromTruncated
}

func validContextFromJobID(id string) bool {
	if len(id) != 32 {
		return false
	}
	for _, r := range id {
		if (r < '0' || r > '9') && (r < 'a' || r > 'f') {
			return false
		}
	}
	return true
}

// DetectSilent returns true ONLY when the final response, after
// TrimSpace, equals the literal "[SILENT]" token. Substring matches,
// alternate casings, and responses that explain the token all return
// false — that's intentional. See spec §7.2.
//
// A false return means "deliver normally" (which is the right default
// for any ambiguous output — the operator would rather see a weird
// message than silently miss one).
func DetectSilent(finalResponse string) bool {
	return strings.TrimSpace(finalResponse) == "[SILENT]"
}

package cron

import (
	"errors"
	"sync"
	"testing"
)

type recordingCloser struct {
	name      string
	mu        *sync.Mutex
	calls     *int
	order     *[]string
	returnErr error
}

func (c *recordingCloser) Close() error {
	c.mu.Lock()
	defer c.mu.Unlock()
	*c.calls++
	*c.order = append(*c.order, c.name)
	return c.returnErr
}

type recordingKiller struct {
	called []int
	err    error
}

func (k *recordingKiller) Kill(pid int) error {
	k.called = append(k.called, pid)
	return k.err
}

func TestRunReleaseLedger_ClosesAllRegisteredClosers(t *testing.T) {
	mu := &sync.Mutex{}
	var calls int
	var order []string
	c1 := &recordingCloser{name: "first", mu: mu, calls: &calls, order: &order}
	c2 := &recordingCloser{name: "second", mu: mu, calls: &calls, order: &order}
	c3 := &recordingCloser{name: "third", mu: mu, calls: &calls, order: &order}

	ledger := NewRunReleaseLedger()
	ledger.RegisterCloser("session-db-a", c1)
	ledger.RegisterCloser("session-db-b", c2)
	ledger.RegisterCloser("session-db-c", c3)

	evidence, err := ledger.Release(nil)
	if err != nil {
		t.Fatalf("Release error = %v", err)
	}
	if calls != 3 {
		t.Fatalf("calls = %d, want 3", calls)
	}
	wantOrder := []string{"first", "second", "third"}
	for i, name := range wantOrder {
		if order[i] != name {
			t.Fatalf("order[%d] = %q, want %q", i, order[i], name)
		}
	}
	closedCount := 0
	for _, ev := range evidence {
		if ev.Code == ReleaseEvidenceSessionDBClosed {
			closedCount++
		}
	}
	if closedCount != 3 {
		t.Fatalf("evidence cron_release_session_db_closed count = %d, want 3 (one per closable)", closedCount)
	}
}

func TestRunReleaseLedger_KillsRegisteredSubprocesses(t *testing.T) {
	killer := &recordingKiller{}
	ledger := NewRunReleaseLedger()
	ledger.RegisterSubprocess(1234)
	ledger.RegisterSubprocess(5678)

	evidence, err := ledger.Release(killer)
	if err != nil {
		t.Fatalf("Release error = %v", err)
	}
	if len(killer.called) != 2 || killer.called[0] != 1234 || killer.called[1] != 5678 {
		t.Fatalf("killer.called = %v, want [1234 5678]", killer.called)
	}
	killedPIDs := map[int]bool{}
	for _, ev := range evidence {
		if ev.Code != ReleaseEvidenceSubprocessKilled {
			continue
		}
		pid, ok := ev.Fields["pid"].(int)
		if !ok {
			t.Fatalf("subprocess evidence pid field = %v, want int", ev.Fields["pid"])
		}
		killedPIDs[pid] = true
	}
	if !killedPIDs[1234] || !killedPIDs[5678] {
		t.Fatalf("expected subprocess_killed evidence for 1234 and 5678; got %v", killedPIDs)
	}
}

func TestRunReleaseLedger_PartialFailureContinues(t *testing.T) {
	mu := &sync.Mutex{}
	var calls int
	var order []string
	c1 := &recordingCloser{name: "first", mu: mu, calls: &calls, order: &order}
	c2 := &recordingCloser{name: "second", mu: mu, calls: &calls, order: &order, returnErr: errors.New("boom")}
	c3 := &recordingCloser{name: "third", mu: mu, calls: &calls, order: &order}

	ledger := NewRunReleaseLedger()
	ledger.RegisterIdleClosable("rt-a", c1)
	ledger.RegisterIdleClosable("rt-b", c2)
	ledger.RegisterIdleClosable("rt-c", c3)

	evidence, err := ledger.Release(nil)
	if err == nil {
		t.Fatalf("Release error = nil, want aggregate failure")
	}
	if calls != 3 {
		t.Fatalf("calls = %d, want 3 (continued past failure)", calls)
	}
	if order[2] != "third" {
		t.Fatalf("third closer not called; order = %v", order)
	}
	failed := false
	for _, ev := range evidence {
		if ev.Code == ReleaseEvidenceHTTPIdleClosedFailed {
			failed = true
			if got := ev.Fields["error"]; got != "boom" {
				t.Fatalf("failed evidence error = %v, want %q", got, "boom")
			}
		}
	}
	if !failed {
		t.Fatalf("evidence = %+v, want one cron_release_http_idle_closed_failed entry", evidence)
	}
}

func TestRunReleaseLedger_NoResourceRecordsSkippedEvidence(t *testing.T) {
	ledger := NewRunReleaseLedger()
	evidence, err := ledger.Release(nil)
	if err != nil {
		t.Fatalf("Release error = %v", err)
	}
	skipped := 0
	for _, ev := range evidence {
		if ev.Code == ReleaseEvidenceSkippedNoResource {
			skipped++
		}
	}
	if skipped != 1 {
		t.Fatalf("evidence = %+v, want exactly one skipped_no_resource entry", evidence)
	}
}

func TestRunReleaseLedger_IsIdempotent(t *testing.T) {
	mu := &sync.Mutex{}
	var calls int
	var order []string
	c := &recordingCloser{name: "only", mu: mu, calls: &calls, order: &order}
	killer := &recordingKiller{}

	ledger := NewRunReleaseLedger()
	ledger.RegisterCloser("session-db", c)
	ledger.RegisterSubprocess(42)

	if _, err := ledger.Release(killer); err != nil {
		t.Fatalf("first Release error = %v", err)
	}
	if calls != 1 || len(killer.called) != 1 {
		t.Fatalf("first release: calls=%d killed=%v, want 1 close + 1 kill", calls, killer.called)
	}

	evidence, err := ledger.Release(killer)
	if err != nil {
		t.Fatalf("second Release error = %v", err)
	}
	if calls != 1 {
		t.Fatalf("close called twice: calls = %d", calls)
	}
	if len(killer.called) != 1 {
		t.Fatalf("kill called twice: killer.called = %v", killer.called)
	}
	if len(evidence) != 1 || evidence[0].Code != ReleaseEvidenceSkippedNoResource {
		t.Fatalf("second release evidence = %+v, want one skipped_no_resource entry", evidence)
	}
}

